		$p.openPopup("wframePopup_layerpopup_WESD-1289_(WSQ-5269)_popup.xml" , options);
	};

	scwin.checkVal = function() {
		return (document.getElementById('testpopup_header') || document.getElementById('mf_testpopup_header')).getElementsByTagName('h2').length == 1;
	}
